const input=$json.body??$json;
const s=v=>String(v??'').trim();
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const propertyType=s(input.property_type??input.property?.type).toLowerCase();
const address=s(input.property_address??input.property?.address);
const id=s(dealId||propertyId||leadId);
const missing=[];
if(!id)missing.push('canonical_identity');
if(!propertyType)missing.push('property_type');
if(!address&&!propertyId)missing.push('property_address_or_property_id');
const evidence=input.evidence??{};
const tasks=[
 {key:'comps',workflow:'wf-071-comps-market-evidence-adapter',path:'/webhook/wf-071-comps-market-evidence-adapter',present:evidence.comps??input.comps},
 {key:'repairs',workflow:'wf-072-repair-cost-property-condition-analysis',path:'/webhook/wf-072-repair-cost-property-condition-analysis',present:evidence.repairs??input.repairs??input.estimated_repairs},
 {key:'risk',workflow:'wf-073-property-risk-feasibility-analysis',path:'/webhook/wf-073-property-risk-feasibility-analysis',present:evidence.risk??input.property_risk??input.risk_evidence},
 {key:'buyer_demand',workflow:'wf-074-buyer-demand-exit-strategy-analysis',path:'/webhook/wf-074-buyer-demand-exit-strategy-analysis',present:evidence.buyer_demand??input.buyer_demand??input.exit_strategy}
].filter(t=>t.present===undefined||t.present===null||t.present==='');
const base=s(input.acquisition_workflow_base_url)||s(input.base_url);\nif(!base)return[{json:{ok:false,status:'blocked',request_id:requestId,missing_requirements:['acquisition_workflow_base_url'],dispatches:[]}}];
const requestId=s(input.request_id)||('evidence-fanout:'+(id||'unknown')+':v1');
if(missing.length)return[{json:{ok:false,status:'needs_context',request_id:requestId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},missing_requirements:missing,dispatches:[]}}];
if(!tasks.length)return[{json:{ok:true,status:'evidence_already_present',request_id:requestId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},dispatches:[],next_workflow:'wf-109-underwriting-evidence-aggregator'}}];
return tasks.map(t=>({json:{request_id:requestId,task_key:t.key,workflow:t.workflow,url:base+t.path,payload:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,property_type:propertyType,address,property_address:address,request_id:requestId,source_workflow:'wf-110'}}}));

const items=$input.all();
const normalized=items.map(i=>{
 const j=i.json??{};
 const status=Number(j.statusCode??j.httpStatus??0);
 const body=j.provider_response??j.body??j.data??j;
 const taskKey=body?.task_key??body?.request?.task_key??j.task_key??null;
 const workflow=body?.workflow??body?.request?.workflow??j.workflow??null;
 const requestId=body?.request_id??body?.request?.request_id??j.request_id??null;
 const ok=(status>=200&&status<300)||body?.ok===true||body?.status==='ready'||body?.status==='evidence_ready';
 return {task_key:taskKey,workflow,request_id:requestId,transport_status:status||null,ok,provider_response:body};
});
const failed=normalized.filter(x=>!x.ok);
return[{json:{ok:failed.length===0,status:failed.length?'evidence_dispatch_partial_failure':'evidence_dispatched',results:normalized,failed_tasks:failed.map(x=>x.task_key),completed_tasks:normalized.filter(x=>x.ok).map(x=>x.task_key),next_workflow:failed.length?null:'wf-109-underwriting-evidence-aggregator'}}];
